// uploadPollURL is the address a row polls: its own fragment, after the books already shown.
func uploadPollURL(v UploadRowView) string {
	u := "/hx/uploads/" + v.ID
	if v.Seen > 0 {
		u += "?seen=" + strconv.Itoa(v.Seen)
	}
	return u
}

